-- Generated by `uv run datasources-db export-evaluation` from populate/event_grouping/ (125 files).
-- Do not edit by hand: add, rename or edit the JSON files, then regenerate and commit.
-- Safe to run again: an existing row is updated only when its file's checksum changed.

ON CONFLICT (filename) DO UPDATE SET test_number = EXCLUDED.test_number,
    fixture_type = EXCLUDED.fixture_type, expected_group = EXCLUDED.expected_group,
    file_checksum = EXCLUDED.file_checksum, updated_at = now()
WHERE evaluation.fixture_file.file_checksum IS DISTINCT FROM EXCLUDED.file_checksum;
